#Requires -Version 5.1
param([string]$KitDirectory="",[string]$InstallDirectory="")
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest
if(!$KitDirectory){$KitDirectory=$PSScriptRoot}; if(!$InstallDirectory){$InstallDirectory=Join-Path (Split-Path -Parent $KitDirectory) 'nids-analysis-runtime'};. (Join-Path $PSScriptRoot 'analysis-kit-common.ps1');$m=Test-AnalysisKit $KitDirectory;$py=Join-Path $InstallDirectory '.venv\Scripts\python.exe';$source=Join-Path $InstallDirectory 'source';if(!(Test-Path $py)){throw 'runtime is missing'};$env:PIP_NO_INDEX='1';Push-Location $source;try{&$py -I -c "import torch; from data_pipeline.offline.class3_analysis_export import export_class3_analysis; from class_1_anomaly_detection.src.model_pipeline import run_gadnr; assert not torch.cuda.is_available(); print('offline_imports=ok')";if($LASTEXITCODE -ne 0){throw 'offline imports failed'};&$py -s -m unittest class_1_anomaly_detection.tests.test_model_pipeline -v;if($LASTEXITCODE -ne 0){throw 'synthetic GAD-NR tests failed'};@{status='passed';network='not_attempted';source_commit=$m.source_commit}|ConvertTo-Json -Compress}finally{Pop-Location}
